DROP POLICY quality_read ON public.quality_items;
CREATE POLICY quality_read ON public.quality_items FOR SELECT TO authenticated USING(public.is_director(auth.uid()) OR (public.is_ops(auth.uid()) AND kind IN ('complaints','improvements','consent','review_request','referral_request','recovery_request','standards')) OR (assigned_user_id=auth.uid() AND public.has_any_role(auth.uid(),ARRAY['veterinario','luis']::public.app_role[]) AND kind IN ('complaints','education','improvements')) OR (owner_id=auth.uid() AND public.has_any_role(auth.uid(),ARRAY['cliente']::public.app_role[]) AND kind IN ('consent','invitation','response','review_request','referral_request')) OR (kind='education' AND state='PUBLISHED' AND (payload->>'validUntil')::timestamptz>=now()) OR (kind='surveys' AND state='PUBLISHED' AND public.has_any_role(auth.uid(),ARRAY['cliente']::public.app_role[]) AND public.quality_has_invitation(id)));